1	type Cell = [number, number];
2	
3	const toKey = ([x, y]: Cell): string => `${x},${y}`;
4	const fromKey = (key: string): Cell => {
5	  const [x, y] = key.split(",").map(Number);
6	  return [x, y];
7	};
8	
9	const survivesNextGeneration = (isAlive: boolean, neighborCount: number): boolean =>
10	  isAlive ? neighborCount === 2 || neighborCount === 3 : neighborCount === 3;
11	
12	const neighborOffsets: Cell[] = [
13	  [-1, -1], [0, -1], [1, -1],
14	  [-1, 0],           [1, 0],
15	  [-1, 1], [0, 1], [1, 1],
16	];
17	
18	export function nextGeneration(cells: Cell[]): Cell[] {
19	  const living = new Set(cells.map(toKey));
20	
21	  const neighborCounts = new Map<string, number>();
22	  for (const [x, y] of cells) {
23	    for (const [dx, dy] of neighborOffsets) {
24	      const key = toKey([x + dx, y + dy]);
25	      neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
26	    }
27	  }
28	
29	  const next: Cell[] = [];
30	  for (const [key, count] of neighborCounts) {
31	    if (survivesNextGeneration(living.has(key), count)) {
32	      next.push(fromKey(key));
33	    }
34	  }
35	  return next;
36	}
