1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return an empty array when given no living cells", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("should kill a single live cell with 0 neighbors — [(0,0)] → []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("Rule 1 Underpopulation: two adjacent cells each with 1 neighbor die — [(0,1),(1,1)] → []", () => {
12	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
13	  });
14	  it("Rule 4 Reproduction: dead cell with exactly 3 neighbors becomes alive — [(0,1),(1,1),(0,0)] includes (1,0)", () => {
15	    expect(nextGeneration([[0, 1], [1, 1], [0, 0]])).toContainEqual([1, 0]);
16	  });
17	  it("Rule 2 Survival: live cell with 2 neighbors lives on — center of a row of 3 [(0,0),(1,0),(2,0)] survives (1,0)", () => {
18	    expect(nextGeneration([[0, 0], [1, 0], [2, 0]])).toContainEqual([1, 0]);
19	  });
20	  it("Rule 3 Overpopulation: live cell with more than 3 neighbors dies — center of ### / .#. / ### dies", () => {
21	    const cells: [number, number][] = [
22	      [0, 0], [1, 0], [2, 0],
23	      [1, 1],
24	      [0, 2], [1, 2], [2, 2],
